impl AntiProjectViaHorizonOnto<MultiVector> for Infinity {
    type Output = MultiVector;
    // Operative Statistics for this implementation:
    //           add/sub      mul      div      pow
    //      f32        7       21        0        0
    //    simd2        0        1        0      N/A
    //    simd3        3        8        0      N/A
    //    simd4        0        1        0      N/A
    // Totals...
    // yes simd       10       31        0      N/A
    //  no simd       16       51        0        0
    fn anti_project_via_horizon_onto(self, other: MultiVector) -> Self::Output {
        use crate::elements::*;
        let anti_wedge_g0_x = self[e5] * other[e4] * -1.0;
        let anti_wedge_g2 = self[e5] * other[scalar];
        MultiVector::from_groups(
            // scalar, e12345
            Simd32x2::from([anti_wedge_g0_x * other[scalar], (anti_wedge_g0_x * other[e12345]) + (anti_wedge_g2 * other[e1234])]),
            // e1, e2, e3, e4
            Simd32x4::from(anti_wedge_g0_x) * other.group1(),
            // e5
            (anti_wedge_g0_x * other[e5]) + (anti_wedge_g2 * other[scalar]),
            // e41, e42, e43, e45
            (Simd32x2::from(anti_wedge_g0_x) * other.group3().xy()).with_zw(anti_wedge_g0_x * other[e43], (anti_wedge_g0_x * other[e45]) + (anti_wedge_g2 * other[e4])),
            // e15, e25, e35
            (Simd32x3::from(anti_wedge_g0_x) * other.group4()) + (Simd32x3::from(anti_wedge_g2) * other.group1().xyz()),
            // e23, e31, e12
            Simd32x3::from(anti_wedge_g0_x) * other.group5(),
            // e415, e425, e435, e321
            ((Simd32x3::from(anti_wedge_g0_x) * other.group6().xyz()) + (Simd32x3::from(anti_wedge_g2) * other.group3().xyz())).with_w(anti_wedge_g0_x * other[e321]),
            // e423, e431, e412
            Simd32x3::from(anti_wedge_g0_x) * other.group7(),
            // e235, e315, e125
            (Simd32x3::from(anti_wedge_g0_x) * other.group8()) + (Simd32x3::from(anti_wedge_g2) * other.group5()),
            // e1234, e4235, e4315, e4125
            Simd32x4::from([
                anti_wedge_g0_x * other[e1234],
                (anti_wedge_g0_x * other[e4235]) + (anti_wedge_g2 * other[e423]),
                (anti_wedge_g0_x * other[e4315]) + (anti_wedge_g2 * other[e431]),
                (anti_wedge_g0_x * other[e4125]) + (anti_wedge_g2 * other[e412]),
            ]),
            // e3215
            (anti_wedge_g0_x * other[e3215]) + (anti_wedge_g2 * other[e321]),
        )
    }
}
