impl AntiProjectViaHorizonOnto<AntiCircleOnOrigin> for Line {
    type Output = Circle;
    // Operative Statistics for this implementation:
    //           add/sub      mul      div      pow
    //      f32        5        9        0        0
    //    simd3        2        7        0      N/A
    //    simd4        2        0        0      N/A
    // Totals...
    // yes simd        9       16        0      N/A
    //  no simd       19       30        0        0
    fn anti_project_via_horizon_onto(self, other: AntiCircleOnOrigin) -> Self::Output {
        use crate::elements::*;
        let anti_wedge_g0 = Simd32x3::from(0.0).with_w((other[e42] * self[e425]) + (other[e43] * self[e435]))
            + (other.group0().yzx() * self.group1().zxy()).with_w(other[e41] * self[e415])
            - (other.group0().zxy() * self.group1().yzx()).with_w(0.0);
        let anti_wedge_g1 = (other[e23] * self[e235]) + (other[e31] * self[e315]) + (other[e12] * self[e125]);
        Circle::from_groups(
            // e423, e431, e412
            (Simd32x3::from(anti_wedge_g0[3]) * other.group1()) + (other.group0().yzx() * anti_wedge_g0.zxy()) - (other.group0().zxy() * anti_wedge_g0.yzx()),
            // e415, e425, e435, e321
            (Simd32x3::from(anti_wedge_g1) * other.group0()).with_w(-(anti_wedge_g0[0] * other[e23]) - (anti_wedge_g0[1] * other[e31]) - (anti_wedge_g0[2] * other[e12])),
            // e235, e315, e125
            Simd32x3::from(anti_wedge_g1) * other.group1(),
        )
    }
}
impl AntiProjectViaHorizonOnto<AntiCircleRotor> for Line {
    type Output = VersorEven;
    // Operative Statistics for this implementation:
    //           add/sub      mul      div      pow
    //      f32       11       19        0        0
    //    simd2        0        2        0      N/A
    //    simd3        4       11        0      N/A
    //    simd4       10        4        0      N/A
    // Totals...
    // yes simd       25       36        0      N/A
    //  no simd       63       72        0        0
    fn anti_project_via_horizon_onto(self, other: AntiCircleRotor) -> Self::Output {
        use crate::elements::*;
        let anti_wedge_g1_xyz = Simd32x3::from(other[scalar]) * self.group0();
        let anti_wedge_g2_xyz = Simd32x3::from(other[scalar]) * self.group1();
        let anti_wedge_g2_w = (other[e41] * self[e415]) + (other[e42] * self[e425]) + (other[e43] * self[e435]);
        let anti_wedge_g3 = (Simd32x4::from([self[e415], self[e425], self[e435], self[e235]]) * other.group1().wwwx())
            + Simd32x3::from(0.0).with_w((other[e12] * self[e125]) + (other[e15] * self[e415]) + (other[e25] * self[e425]) + (other[e35] * self[e435]))
            + (other.group0().yzx() * self.group1().zxy()).with_w(other[e31] * self[e315])
            - (other.group0().zxy() * self.group1().yzx()).with_w(0.0);
        VersorEven::from_groups(
            // e423, e431, e412, e12345
            Simd32x3::from(0.0).with_w(
                -(anti_wedge_g1_xyz[1] * other[e31])
                    - (anti_wedge_g1_xyz[2] * other[e12])
                    - (anti_wedge_g2_xyz[0] * other[e41])
                    - (anti_wedge_g2_xyz[1] * other[e42])
                    - (anti_wedge_g2_xyz[2] * other[e43]),
            ) + (Simd32x3::from(anti_wedge_g2_w) * other.group1().xyz()).with_w(0.0)
                + (other.group0().yzx() * anti_wedge_g3.zxy()).with_w(0.0)
                - (Simd32x4::from([anti_wedge_g3[1], anti_wedge_g3[2], anti_wedge_g3[0], anti_wedge_g1_xyz[0] * other[e23]]) * other.group0().zxy().with_w(1.0)),
            // e415, e425, e435, e321
            Simd32x3::from(0.0).with_w(-(anti_wedge_g3[1] * other[e31]) - (anti_wedge_g3[2] * other[e12]))
                + (anti_wedge_g1_xyz * Simd32x3::from(other[scalar])).with_w(0.0)
                + (Simd32x3::from(anti_wedge_g2_w) * other.group2().xyz()).with_w(0.0)
                + (Simd32x3::from(anti_wedge_g3[3]) * other.group0()).with_w(0.0)
                - (anti_wedge_g3.xyzx() * other.group1().wwwx()),
            // e235, e315, e125, e5
            ((anti_wedge_g2_xyz * Simd32x3::from(other[scalar]))
                + (Simd32x3::from(anti_wedge_g3[3]) * other.group1().xyz())
                + Simd32x2::from(0.0).with_z((anti_wedge_g3[0] * other[e25]) - (anti_wedge_g3[1] * other[e15]))
                + (anti_wedge_g3.yz() * other.group2().zx()).with_z(0.0)
                - (anti_wedge_g3.zx() * other.group2().yz()).with_z(0.0))
            .with_w(anti_wedge_g3[3] * other[scalar]),
            // e1, e2, e3, e4
            Simd32x4::from(other[scalar]) * anti_wedge_g3.xyz().with_w(anti_wedge_g2_w),
        )
    }
}
